{
  "name": "open-generative-ai",
  "description": "Open-source alternative to HF AI — AI image, video, cinema and lip sync studio",
  "homepage": "https://github.com/Anil-matcha/Open-Generative-AI",
  "private": true,
  "version": "2.0.0",
  "license": "MIT",
  "workspaces": [
    "packages/studio",
    "packages/Vibe-Workflow/packages/workflow-builder",
    "packages/Open-Poe-AI/packages/agents",
    "packages/Open-AI-Design-Agent/packages/design-agent"
  ],
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "next lint",
    "build:studio": "npm run build -w studio",
    "build:workflow": "npm run build -w workflow-builder",
    "build:agent": "npm run build -w ai-agent",
    "build:design": "npm run build -w design-agent",
    "build:packages": "npm run build:workflow && npm run build:agent && npm run build:design && npm run build:studio",
    "setup": "git submodule update --init --recursive && npm install && npm run build:packages",
    "vite:dev": "vite",
    "vite:build": "vite build",
    "electron:dev": "npm run vite:build && electron .",
    "electron:build": "vite build && electron-builder --mac",
    "electron:build:win": "vite build && electron-builder --win",
    "electron:build:linux": "vite build && electron-builder --linux",
    "electron:build:linux:dir": "vite build && electron-builder --linux dir",
    "electron:build:linux:arm64:dir": "vite build && electron-builder --linux dir --arm64",
    "stage:local-ai": "node scripts/stage-local-ai-binary.js",
    "package:linux:deb": "node scripts/package-linux-deb.js",
    "package:linux:deb:arm64": "node scripts/package-linux-deb.js --arch arm64",
    "package:linux:deb:x64": "node scripts/package-linux-deb.js --arch x64",
    "electron:build:all": "vite build && electron-builder --mac --win --linux"
  },
  "build": {
    "appId": "ai.generative.open",
    "productName": "Open Generative AI",
    "copyright": "Copyright © 2025",
    "directories": {
      "output": "release"
    },
    "afterPack": "./afterPack.js",
    "files": [
      "dist/**/*",
      "electron/**/*"
    ],
    "extraResources": [
      {
        "from": "build/local-ai",
        "to": "local-ai",
        "filter": [
          "**/*"
        ]
      }
    ],
    "mac": {
      "category": "public.app-category.graphics-design",
      "icon": "public/banner.png",
      "gatekeeperAssess": false,
      "target": [
        {
          "target": "dmg",
          "arch": [
            "x64",
            "arm64"
          ]
        }
      ]
    },
    "win": {
      "icon": "public/banner.png",
      "signAndEditExecutable": false,
      "target": [
        {
          "target": "nsis",
          "arch": [
            "x64"
          ]
        }
      ]
    },
    "nsis": {
      "oneClick": false,
      "allowToChangeInstallationDirectory": true,
      "include": "build/installer.nsh"
    },
    "linux": {
      "icon": "public/banner.png",
      "category": "Utility",
      "maintainer": "Open Generative AI Team",
      "extraFiles": [
        {
          "from": "build/linux/apparmor.profile",
          "to": "resources/apparmor.profile"
        }
      ],
      "target": [
        {
          "target": "AppImage",
          "arch": [
            "x64"
          ]
        },
        {
          "target": "deb",
          "arch": [
            "x64"
          ]
        }
      ]
    }
  },
  "dependencies": {
    "ai-agent": "file:./packages/Open-Poe-AI/packages/agents",
    "axios": "^1.7.0",
    "next": "^15.0.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0",
    "react-hot-toast": "^2.4.1",
    "studio": "*",
    "workflow-builder": "file:./packages/Vibe-Workflow/packages/workflow-builder",
    "xtend": "^4.0.2"
  },
  "devDependencies": {
    "@eslint/eslintrc": "^3",
    "@tailwindcss/vite": "^4.1.18",
    "autoprefixer": "^10.4.24",
    "electron": "^33.4.11",
    "electron-builder": "^25.1.8",
    "eslint": "^9",
    "eslint-config-next": "^15.0.0",
    "postcss": "^8.5.6",
    "tailwindcss": "^3.4.0",
    "vite": "^5.4.0"
  },
  "main": "electron/main.js"
}

{
  "name": "@askjo/camofox-browser",
  "version": "1.14.0",
  "description": "Headless browser automation server and OpenClaw plugin for AI agents - anti-detection, element refs, and session isolation",
  "type": "module",
  "main": "server.js",
  "license": "MIT",
  "author": "Jo Inc <oss@askjo.ai>",
  "homepage": "https://github.com/jo-inc/camofox-browser#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jo-inc/camofox-browser.git"
  },
  "bugs": {
    "url": "https://github.com/jo-inc/camofox-browser/issues"
  },
  "keywords": [
    "browser",
    "automation",
    "headless",
    "scraping",
    "camofox",
    "camoufox",
    "anti-detection",
    "ai-agent",
    "openclaw",
    "clawdbot",
    "moltbot",
    "playwright",
    "firefox",
    "youtube",
    "transcript"
  ],
  "engines": {
    "node": ">=22"
  },
  "files": [
    "server.js",
    "lib/",
    "plugins/",
    "camofox.config.json",
    "plugin.ts",
    "plugin.js",
    "dist/plugin.js",
    "tsconfig.json",
    "openclaw.plugin.json",
    "mcp/",
    "bin/",
    "scripts/",
    "run.sh",
    "Dockerfile",
    "README.md",
    "LICENSE",
    "AGENTS.md",
    "!**/*.test.js",
    "!**/*.test.ts",
    "!**/*.spec.js"
  ],
  "openclaw": {
    "extensions": [
      "plugin.ts"
    ],
    "runtimeExtensions": [
      "plugin.js"
    ],
    "compat": {
      "pluginApi": ">=2026.3.24-beta.2"
    },
    "build": {
      "openclawVersion": "2026.5.3"
    },
    "tools": [
      {
        "name": "camofox_create_tab",
        "description": "Open a new browser tab at a URL"
      },
      {
        "name": "camofox_snapshot",
        "description": "Get accessibility snapshot with element refs"
      },
      {
        "name": "camofox_click",
        "description": "Click an element by ref or CSS selector"
      },
      {
        "name": "camofox_type",
        "description": "Type text into an element"
      },
      {
        "name": "camofox_navigate",
        "description": "Navigate to URL or search macro"
      },
      {
        "name": "camofox_scroll",
        "description": "Scroll page up/down/left/right"
      },
      {
        "name": "camofox_screenshot",
        "description": "Capture page screenshot"
      },
      {
        "name": "camofox_close_tab",
        "description": "Close a browser tab"
      },
      {
        "name": "camofox_evaluate",
        "description": "Execute JavaScript in a Camoufox tab page context"
      },
      {
        "name": "camofox_list_tabs",
        "description": "List open tabs for a user"
      },
      {
        "name": "camofox_import_cookies",
        "description": "Import Netscape cookie file (requires CAMOFOX_API_KEY)"
      }
    ]
  },
  "scripts": {
    "build": "tsc -p . || true; mkdir -p dist && cp plugin.js dist/plugin.js",
    "prepublishOnly": "npm run build",
    "start": "node server.js",
    "mcp": "node mcp/server.mjs",
    "test:mcp": "npm ci --prefix mcp && node scripts/test-mcp.mjs && node scripts/test-mcp-package.mjs",
    "test:unit": "NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit tests/unit",
    "test": "npm run test:unit && npm run test:e2e && npm run test:plugins",
    "test:e2e": "NODE_OPTIONS='--experimental-vm-modules' jest --config jest.config.e2e.cjs --runInBand --forceExit",
    "test:plugins": "NODE_OPTIONS='--experimental-vm-modules' jest --forceExit plugins/",
    "test:live": "RUN_LIVE_TESTS=1 NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit tests/live",
    "test:debug": "DEBUG_SERVER=1 NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit",
    "plugin": "node scripts/plugin.js",
    "generate-openapi": "node scripts/generate-openapi.js",
    "version:sync": "node scripts/sync-version.js",
    "version": "node scripts/sync-version.js && node scripts/generate-openapi.js && git add openclaw.plugin.json mcp/package.json mcp/package-lock.json openapi.json",
    "postinstall": "node scripts/postinstall.js",
    "fetch-bin": "npx camoufox-js fetch"
  },
  "dependencies": {
    "better-sqlite3": "13.0.1",
    "camoufox-js": "0.11.5",
    "express": "^5.2.1",
    "playwright-core": "^1.58.0",
    "prom-client": "^15.1.3",
    "swagger-jsdoc": "^6.2.8"
  },
  "optionalDependencies": {
    "@modelcontextprotocol/sdk": "^1.30.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "jest": "^30.4.2",
    "pngjs": "^7.0.0",
    "typescript": "^5.7.0"
  },
  "overrides": {
    "@jest/reporters": {
      "glob": "13.0.6"
    },
    "babel-plugin-istanbul": {
      "test-exclude": "8.0.0"
    },
    "jest-config": {
      "glob": "13.0.6"
    },
    "jest-runtime": {
      "glob": "13.0.6"
    },
    "swagger-jsdoc": {
      "glob": "13.0.6"
    }
  },
  "bin": {
    "camofox-browser": "./bin/camofox-browser.js",
    "camofox-browser-mcp": "./mcp/server.mjs"
  }
}

[workspace]
default-members = ["crates/story"]
members = [
    "crates/kit",
    "crates/base",
    "crates/base/examples/wasm",
    "crates/base/examples/native",
    "crates/component-macros",
    "crates/story",
    "crates/story-web",
    "crates/component",
    "crates/assets",
    "crates/fps",
    "crates/webview",
    "examples/app_assets",
    "examples/fps_monitor",
    "examples/hello_world",
    "examples/input",
    "examples/editor",
    "examples/brush",
    "examples/dock",
    "examples/html",
    "examples/large-text",
    "examples/markdown",
    "examples/stream-markdown",
    "examples/tiles",
    "examples/window_title",
    "examples/dialog_overlay",
    "examples/webview",
    "examples/system_monitor",
    "examples/focus_trap",
    "examples/tooltip_top_edge",
    "examples/sidebar",
    "examples/text_max_lines",
    "examples/text_selection",
    "examples/root_borderless",
    "examples/table_in_scrollable",
    "examples/markdown_table",
    "crates/shell",
    "crates/component-shell",
]
resolver = "2"

[workspace.package]
publish = false
edition = "2024"

[workspace.dependencies]
gpui-kit = { path = "crates/kit", version = "0.6.0" }
gpui-component = { path = "crates/component", version = "0.6.0" }
gpui-base = { path = "crates/base", version = "0.6.0" }
gpui-component-macros = { path = "crates/component-macros", version = "0.6.0" }
gpui-kit-assets = { path = "crates/assets", version = "0.6.0" }
gpui-fps = { path = "crates/fps", version = "0.6.0" }
gpui-shell = { path = "crates/shell", version = "0.6.0" }
gpui-wry = { path = "crates/webview", version = "0.6.0" }
gpui-component-shell = { path = "crates/component-shell", version = "0.6.0" }
story = { path = "crates/story" }

gpui = { package = "gpui-pre", version = "0.3.1" }
gpui_platform = { package = "gpui-pre-platform", version = "0.3.1", features = ["font-kit", "x11", "wayland", "runtime_shaders"] }
gpui_web = { package = "gpui-pre-web", version = "0.3.1" }
gpui_macros = { package = "gpui-pre-macros", version = "0.3.1" }
reqwest_client = { package = "gpui-pre-reqwest-client", version = "0.3.1" }
sum-tree = { package = "gpui-pre-sum-tree", version = "0.3.1" }
reqwest = { package = "gpui-pre-reqwest", version = "0.12.15", default-features = false, features = [
    "charset",
    "http2",
    "macos-system-configuration",
    "multipart",
    "rustls-tls-native-roots",
    "socks",
    "stream",
] }

anyhow = "1"
instant = { version = "0.1", features = ["wasm-bindgen"] }
log = "0.4"
lsp-types = { version = "0.97.0", features = ["proposed"] }
notify = "7.0.0"
raw-window-handle = "0.6.2"
ropey = { version = "=2.0.0-beta.1", features = [
    "metric_chars",
    "metric_lines_lf",
    "metric_utf16",
] }
rust-i18n = "4.2.0"
schemars = "1"
semver = "1"
serde = { version = "1.0.219", features = ["derive"] }
serde_json = "1"
serde_repr = "0.1"
smallvec = "1"
smol = "2"
syntect = { version = "5.3.0", default-features = false, features = [
    "parsing",
    "default-syntaxes",
    "regex-fancy",
] }
tracing = "0.1.41"
wasm-bindgen = "0.2.113"
# Use errno stub for WASM
errno = { version = "0.3.14", default-features = false }

[workspace.dependencies.windows]
features = ["Wdk", "Wdk_System", "Wdk_System_SystemServices"]
version = "0.58.0"

[workspace.lints.clippy]
almost_complete_range = "allow"
arc_with_non_send_sync = "allow"
borrowed_box = "allow"
dbg_macro = "deny"
let_underscore_future = "allow"
manual_is_multiple_of = "allow"
map_entry = "allow"
module_inception = "allow"
non_canonical_partial_ord_impl = "allow"
reversed_empty_ranges = "allow"
single_range_in_vec_init = "allow"
style = { level = "allow", priority = -1 }
todo = "deny"
type_complexity = "allow"
# Temporarily allow this until we can migrate to the new APIs.
# https://github.com/longbridge/gpui-kit/pull/2149
useless_conversion = "allow"

[profile.dev]
codegen-units = 16
debug = "limited"
split-debuginfo = "unpacked"

[profile.dev.package]
resvg = { opt-level = 3 }
rustybuzz = { opt-level = 3 }
taffy = { opt-level = 3 }
ttf-parser = { opt-level = 3 }
smol = { opt-level = 3 }
gpui-pre = { opt-level = 3 }
gpui-pre-platform = { opt-level = 3 }
gpui-pre-macros = { opt-level = 3 }
tree-sitter = { opt-level = 3 }
gpui-pre-sum-tree = { opt-level = 3 }
ropey = { opt-level = 3 }
lsp-types = { opt-level = 3 }
gpui-pre-reqwest-client = { opt-level = 3 }
markdown = { opt-level = 3 }
xml5ever = { opt-level = 3 }
# `rquickjs` is a facade that re-exports `rquickjs-core`, so naming it alone
# optimises neither the interpreter nor the bindings. `rquickjs-sys` builds
# QuickJS itself through `cc`, which reads this package's opt-level; without
# these two a debug build spends roughly three times as long in every script
# render. See `website/shell/hosting.md`.
rquickjs = { opt-level = 3 }
rquickjs-sys = { opt-level = 3 }
rquickjs-core = { opt-level = 3 }
cap-std = { opt-level = 3 }

[workspace.metadata.typos]
files.extend-exclude = ["**/fixtures/*"]

[workspace.metadata.typos.default.exten

{
	"private": true,
	"packageManager": "pnpm@10.4.1",
	"scripts": {
		"format": "prettier --write .",
		"format:check": "prettier --check .",
		"check-types": "tsc --noEmit -p desktop/tsconfig.json && tsc --noEmit -p website/tsconfig.json"
	},
	"devDependencies": {
		"prettier": "^3.5.3",
		"typescript": "^5.9.3"
	}
}
